{
  "claims": [
    {
      "anchor": "A shared cache may reuse a cached response to a request with an Authorization header whenever the response is fresh.",
      "claim_text": "A shared cache may reuse a cached response to a request with an Authorization header whenever the response is fresh.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P0.S0", "rel": "refutes"}
      ],
      "check": null,
      "reasoning": "Passage forbids reuse unless a Cache-Control directive allows it; freshness alone is not sufficient."
    },
    {
      "anchor": "When a stored response is served without validation, the cache must generate an Age header equal to the response's current_age.",
      "claim_text": "When a stored response is served without validation, the cache must generate an Age header equal to the response's current_age.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P1.S0", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Direct restatement of P1.S0."
    },
    {
      "anchor": "If several suitable responses are stored, the cache must use the oldest one.",
      "claim_text": "If several suitable responses are stored, the cache must use the oldest one.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P2.S0", "rel": "refutes"}
      ],
      "check": null,
      "reasoning": "Passage requires the most recent, not the oldest."
    },
    {
      "anchor": "A cache may serve a stale response whenever it is disconnected, even if the response carries must-revalidate",
      "claim_text": "A cache may serve a stale response whenever it is disconnected, even if the response carries must-revalidate.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P7.S1", "rel": "refutes"}
      ],
      "check": null,
      "reasoning": "Passage forbids reusing stale response when disconnected with must-revalidate."
    },
    {
      "anchor": "when it cannot revalidate such a response it should return 502 (Bad Gateway).",
      "claim_text": "When a cache cannot revalidate a must-revalidate response, it should return 502 (Bad Gateway).",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P7.S2", "rel": "refutes"}
      ],
      "check": null,
      "reasoning": "Passage says status SHOULD be 504, not 502."
    },
    {
      "anchor": "A cache must invalidate the target URI after a non-error response to an unsafe method",
      "claim_text": "A cache must invalidate the target URI after a non-error response to an unsafe method.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P4.S0", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "Direct restatement of P4.S0."
    },
    {
      "anchor": "it may also invalidate URIs from the Location header even when their origin differs.",
      "claim_text": "A cache may invalidate URIs from the Location header even when their origin differs from the target URI.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P5.S1", "rel": "entails"},
        {"sid": "P5.S2", "rel": "refutes"}
      ],
      "check": null,
      "reasoning": "P5.S1 lists Location as candidate, but P5.S2 forbids invalidation when origin differs."
    },
    {
      "anchor": "The no-store request directive only applies to shared caches.",
      "claim_text": "The no-store request directive only applies to shared caches.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P6.S1", "rel": "refutes"}
      ],
      "check": null,
      "reasoning": "Passage says it applies to both private and shared caches."
    },
    {
      "anchor": "The unqualified private directive forbids shared caches from storing the response but lets a private cache store it.",
      "claim_text": "The unqualified private directive forbids shared caches from storing the response but lets a private cache store it.",
      "kind": "direct",
      "sure": true,
      "evidence": [
        {"sid": "P8.S0", "rel": "entails"},
        {"sid": "P8.S1", "rel": "entails"}
      ],
      "check": null,
      "reasoning": "P8.S0 forbids shared caches; P8.S1 allows private caches."
    }
  ]
}
